CREATE TABLE store_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text, order_number text NOT NULL UNIQUE, customer_name text NOT NULL, email text NOT NULL, phone text NOT NULL, address jsonb NOT NULL, subtotal integer NOT NULL, discount integer NOT NULL DEFAULT 0, shipping integer NOT NULL DEFAULT 0, total integer NOT NULL, coupon_code text, payment_method text NOT NULL, payment_status text NOT NULL DEFAULT 'pending', order_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now())